// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 v, uint256 extra) public {
        // keep values wide but admissible: the contract must hold MORE than v
        v = bound(v, 0, 1e30);
        extra = bound(extra, 1 wei, 1e30);
        vm.assume(v < type(uint256).max - extra);

        // fund the contract with v + extra through its payable fallback
        uint256 total = v + extra;
        vm.deal(address(this), total);
        (bool okFund,) = address(c).call{value: total}("");
        assertTrue(okFund);
        assertEq(address(c).balance, total);

        // owner withdraws exactly v
        uint256 ownerBefore = address(this).balance;
        vm.prank(address(this));
        c.withdraw(v);

        // RULE: the owner receives exactly v, regardless of any extra balance held.
        assertTrue(address(this).balance == ownerBefore + v);
    }

    // allow this test contract to receive the withdrawn Ether
    receive() external payable {}
}
